1	/**
2	 * LEAD-DB bulk loader — import a large CSV or JSON file of leads into a named
3	 * EmailList, server-side, using the SAME idempotent dedup/ingest logic as the
4	 * admin importer (lib/coldemail/import.ts + lib/coldemail/lead-store.ts). Use this
5	 * instead of the web importer for big files (tens of thousands of rows) — there's
6	 * no request timeout here.
7	 *
8	 * IDEMPOTENT: re-running the same file inserts 0 (all rows match existing and are
9	 * updated in place). DEAD/suppressed contacts are never resurrected.
10	 *
11	 * Usage:
12	 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Q3 prospects"
13	 *   npx tsx scripts/import-leads.ts --file leads.json --list-id <listId> --consent
14	 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Cold UK" --create-list
15	 *
16	 * Flags:
17	 *   --file <path>        CSV or JSON file (JSON = array of objects; keys use the
18	 *                        same header names/aliases as CSV). Required.
19	 *   --list <name>        Target list by name. Errors if ambiguous/absent unless
20	 *                        --create-list is given.
21	 *   --list-id <id>       Target list by id (takes precedence over --list).
22	 *   --create-list        Create the list (by --list name) if it doesn't exist.
23	 *   --consent            Record a LEGITIMATE_INTEREST consent row for each NEW contact.
24	 *   --note <text>        Provenance note stored on the ImportBatch — how/where this
25	 *                        batch was sourced (e.g. "Manual research via <directory URL>,
26	 *                        2026-08-25"). ALWAYS pass this for a research-sourced batch;
27	 *                        it's the only batch-level record of provenance (see the
28	 *                        `sourceUrl` column for PER-CONTACT provenance, below).
29	 *   --dry-run            Parse + report row counts only; write nothing.
30	 *
31	 * CSV headers spec: see docs/DOCUMENTATION.md (Lead database → Import). Minimum: an
32	 * `email` column. Everything else (name, fullName, title, website, phone, city, …)
33	 * is optional and mapped through IMPORT_HEADER_ALIASES. A `source`/`sourceUrl` column
34	 * (the specific URL this contact's email was found on) is recorded on that contact's
35	 * ConsentRecord.note when --consent is passed, so provenance is checkable per-contact.
36	 */
37	import { readFileSync } from "node:fs";
38	import { db } from "../lib/db";
39	import {
40	  ingestLeads,
41	  parseCsv,
42	  csvToLeadRows,
43	  IMPORT_HEADER_ALIASES,
44	  type LeadRow,
45	} from "../lib/coldemail/import";
46	import { prismaLeadStore } from "../lib/coldemail/lead-store";
47	
48	function arg(name: string): string | undefined {
49	  const i = process.argv.indexOf(`--${name}`);
50	  return i !== -1 ? process.argv[i + 1] : undefined;
51	}
52	function flag(name: string): boolean {
53	  return process.argv.includes(`--${name}`);
54	}
55	
56	/** Map an arbitrary JSON object's keys onto canonical LeadRow fields via the aliases. */
57	function jsonObjToLeadRow(obj: Record<string, unknown>): LeadRow {
58	  const lead: LeadRow = {};
59	  for (const [k, v] of Object.entries(obj)) {
60	    const field = IMPORT_HEADER_ALIASES[k.trim().toLowerCase()];
61	    if (field && v != null) lead[field] = String(v).trim();
62	  }
63	  return lead;
64	}
65	
66	async function main(): Promise<void> {
67	  const filePath = arg("file");
68	  if (!filePath) {
69	    console.error("ERROR: --file <path> is required. See the header of this script for usage.");
70	    process.exit(1);
71	  }
72	
73	  const listName = arg("list");
74	  const listIdArg = arg("list-id");
75	  const createList = flag("create-list");
76	  const recordConsent = flag("consent");
77	  const dryRun = flag("dry-run");
78	  const note = arg("note") ?? "";
79	
80	  // ---- Load + parse the file into LeadRow[] ----
81	  const raw = readFileSync(filePath, "utf8");
82	  let rows: LeadRow[];
83	  if (filePath.toLowerCase().endsWith(".json")) {
84	    const parsed = JSON.parse(raw);
85	    if (!Array.isArray(parsed)) throw new Error("JSON file must be an array of lead objects.");
86	    rows = parsed.map((o) => jsonObjToLeadRow(o as Record<string, unknown>));
87	  } else {
88	    const { headers, rows: csvRows } = parseCsv(raw);
89	    if (headers.length === 0) throw new Error("Could not parse a header row from the CSV.");
90	    rows = csvToLeadRows(headers, csvRows);
91	  }
92	  console.log(`Parsed ${rows.length} row(s) from ${filePath}.`);
93	
94	  if (dryRun) {
95	    console.log("--dry-run: no changes written.");
96	    await db.$disconnect();
97	    return;
98	  }
99	
100	  // ---- Resolve the target list ----
101	  let listId: string | null = null;
102	  if (listIdArg) {
103	    const list = await db.emailList.findUnique({ where: { id: listIdArg }, select: { id: true } });
104	    if (!list) throw new Error(`No list with id ${listIdArg}.`);
105	    listId = list.id;
106	  } else if (listName) {
107	    const matches = await db.emailList.findMany({ where: { name: listName }, select: { id: true } });
108	    if (matches.length === 1) listId = matches[0].id;
109	    else if (matches.length === 0) {
110	      if (!createList) throw new Error(`No list named "${listName}". Pass --create-list to create it.`);
111	      const created = await db.emailList.create({ data: { name: listName }, select: { id: true } });
112	      listId = created.id;
113	      console.log(`Created list "${listName}" (${listId}).`);
114	    } else {
115	      throw new Error(`"${listName}" is ambiguous (${matches.length} lists). Use --list-id.`);
116	    }
117	  } else {
118	    console.log("No --list/--list-id given — importing into the lead DB without list assignment.");
119	  }
120	
121	  // ---- Ingest via the shared, idempotent core ----
122	  const batch = await db.importBatch.create({
123	    data: {
124	      name: `Script import ${new Date().toISOString().slice(0, 16)}`,
125	      source: "script",
126	      listId,
127	      note,
128	    },
129	    select: { id: true },
130	  });
131	
132	  const result = await ingestLeads(rows, {
133	    store: prismaLeadStore("script"),
134	    listId,
135	    batchId: batch.id,
136	    recordConsent,
137	    consentSource: "script import",
138	  });
139	
140	  await db.importBatch.update({
141	    where: { id: batch.id },
142	    data: {
143	      totalRows: result.totalRows,
144	      inserted: result.inserted,
145	      updated: result.updated,
146	      skippedDead: result.skippedDead,
147	      skippedDup: result.skippedDup,
148	      skippedInvalid: result.skippedInvalid,
149	    },
150	  });
151	
152	  console.log("Import complete:");
153	  console.log(`  inserted (new):          ${result.inserted}`);
154	  console.log(`  updated (existing):      ${result.updated}`);
155	  console.log(`  skipped dead/suppressed: ${result.skippedDead}`);
156	  console.log(`  skipped in-file dupes:   ${result.skippedDup}`);
157	  console.log(`  skipped invalid (no email): ${result.skippedInvalid}`);
158	  console.log(`  batch id: ${batch.id}`);
159	
160	  await db.$disconnect();
161	}
162	
163	main().catch(async (err) => {
164	  console.error("Import failed:", err?.message ?? err);
165	  await db.$disconnect().catch(() => null);
166	  process.exit(1);
167	});
